// --help text and the pager, as the workbench always produced them.
//
// help-golden.json is every parser's format_help() at width 78, generated by
// executing the workbench's own parser-building code (its add_argument calls,
// argument groups, subcommand registration and formatter classes) against a
// recording parser and laying it out with the standard formatter's rules.
// 157 of the 171 texts are the upstream text byte for byte; the fourteen listed
// in DEVIATIONS say what romdev actually does, and are pinned here as romdev's
// own text.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { runCommand, runCommandIsolated } from "../src/decomp/workbench/cli.js";
import { emitLines } from "../src/decomp/workbench/terminal.js";
import { wrap, formatParserHelp, SUPPRESS } from "../src/decomp/workbench/help-format.js";

const GOLDEN = JSON.parse(readFileSync(fileURLToPath(new URL("./fixtures/workbench/help-golden.json", import.meta.url)), "utf8"));

/** Where romdev's help text deliberately differs from upstream, and why. */
const DEVIATIONS = {
  "decomp-workbench shift rehearse analyze": "a campaign citation names a commercial title; romdev says \"the reference campaign\"",
  "decomp-workbench capture-make": "the capture wrapper is a node script, not a POSIX shell script",
  "decomp-workbench permute-sweep": "--permuter-dir holds romdev's JS permuter programs, not a Python checkout",
  "decomp-workbench permute-doctor": "--permuter-dir holds romdev's JS permuter programs, not a Python checkout",
  "decomp-workbench permute sweep": "--permuter-dir holds romdev's JS permuter programs, not a Python checkout",
  "decomp-workbench permute doctor": "--permuter-dir holds romdev's JS permuter programs, not a Python checkout",
  "decomp-workbench doctor": "doctor reports the node runtime, not a Python interpreter",
  "decomp-workbench view": "plain wording: --emit-force-spec help drops \"honest\"",
  "decomp-workbench view-dumps": "plain wording: --emit-force-spec help drops \"honest\"",
  "decomp-workbench diagnose": "plain wording: --emit-force-spec help drops \"honest\"",
  "decomp-workbench diagnose-dumps": "plain wording: --emit-force-spec help drops \"honest\"",
  "decomp-workbench object": "plain wording: the score subcommand help drops \"honest\"",
  "decomp-workbench note-reserve": "plain wording: drops \"honestly\"",
  "decomp-workbench fetch-scratch": "plain wording: drops \"honestly\"",
};

test("every parser's --help is the recorded text", async () => {
  const saved = process.env.COLUMNS;
  process.env.COLUMNS = "80";
  try {
    const wrong = [];
    for (const [prog, want] of Object.entries(GOLDEN)) {
      const r = await runCommand([...prog.split(" ").slice(1), "--help"]);
      if (r.stdout !== want) wrong.push(prog);
    }
    assert.deepEqual(wrong, []);
    assert.equal(Object.keys(GOLDEN).length, 171);
    for (const prog of Object.keys(DEVIATIONS)) assert.ok(prog in GOLDEN, prog);
  } finally { if (saved === undefined) delete process.env.COLUMNS; else process.env.COLUMNS = saved; }
});

test("help lays out for the terminal's width, and a captured run gets 80 columns", async () => {
  const saved = process.env.COLUMNS;
  try {
    process.env.COLUMNS = "60";
    const narrow = await runCommand(["trace", "scheduler", "--help"]);
    // Wrapped prose fits the width; usage tokens are never broken, as upstream.
    const body = narrow.stdout.slice(narrow.stdout.indexOf("\n\n"));
    assert.ok(body.split("\n").every((l) => l.length <= 58), body);
    assert.notEqual(narrow.stdout, GOLDEN["decomp-workbench trace-scheduler"]);
    delete process.env.COLUMNS;
    const isolated = await runCommandIsolated(["trace", "scheduler", "--help"]);
    assert.equal(isolated.stdout, GOLDEN["decomp-workbench trace-scheduler"]);
  } finally { if (saved === undefined) delete process.env.COLUMNS; else process.env.COLUMNS = saved; }
});

test("a usage error prints the command's usage and the error line", async () => {
  const r = await runCommand(["trace", "scheduler"]);
  assert.equal(r.code, 2);
  assert.ok(r.stderr.startsWith("usage: decomp-workbench trace-scheduler [-h] [--against AGAINST]"));
  assert.ok(r.stderr.endsWith("decomp-workbench trace-scheduler: error: the following arguments are required: trace\n"));
});

test("a bare group word prints its part of the journey map; --help prints the group parser", async () => {
  const cache = await runCommand(["cache"]);
  assert.equal(cache.code, 0);
  assert.match(cache.stdout, /^Journey command map\n/);
  assert.match(cache.stdout, /\n  cache status /);
  const help = await runCommand(["cache", "--help"]);
  assert.match(help.stdout, /^usage: decomp-workbench cache \[-h\] \{status,prune,restore\} \.\.\./);
});

test("a boolean option answers to its --no- spelling", async () => {
  const r = await runCommand(["campaign", "--help"]);
  assert.match(r.stdout, /\[--stop-on-exact \| --no-stop-on-exact\]/);
  assert.match(r.stdout, /--stop-on-exact, --no-stop-on-exact/);
});

test("the pager engages only on a terminal, when asked or when the text is taller", () => {
  const io = () => { const x = { out: [], write: (s) => x.out.push(s), paged: 0, page: (s) => { x.paged++; x.out.push(s); } }; return x; };
  const lines = Array.from({ length: 30 }, (_, i) => `line ${i}`);
  const captured = io();
  emitLines(captured, lines, { width: 0, pager: "auto" });
  assert.equal(captured.paged, 0);
  const tall = io(); tall.terminal = { isTTY: true, rows: 24, columns: 80 };
  emitLines(tall, lines, { width: 0, pager: "auto" });
  assert.equal(tall.paged, 1);
  const short = io(); short.terminal = { isTTY: true, rows: 50, columns: 80 };
  emitLines(short, lines, { width: 0, pager: "auto" });
  assert.equal(short.paged, 0);
  const always = io();
  emitLines(always, lines, { width: 0, pager: "always" });
  assert.equal(always.paged, 1);
  const never = io(); never.terminal = { isTTY: true, rows: 5, columns: 80 };
  emitLines(never, lines, { width: 0, pager: "never" });
  assert.equal(never.paged, 0);
  assert.equal(always.out.join(""), lines.join("\n") + "\n");
});

test("a paging command tells its terminal-owning caller to page", async () => {
  const d = fileURLToPath(new URL("./fixtures/workbench/", import.meta.url));
  const r = await runCommand(["view-dumps", `${d}register-mismatch.objdump.txt`, `${d}register-mismatch.objdump.txt`, "--pager", "always", "--color", "never"], { terminal: { isTTY: true, rows: 3, columns: 100 } });
  assert.equal(r.page, true, r.stderr);
  const colored = await runCommand(["view-dumps", `${d}register-mismatch.objdump.txt`, `${d}register-mismatch.objdump.txt`], { terminal: { isTTY: true, rows: 300, columns: 100 } });
  assert.match(colored.stdout, /\x1b\[/);
  assert.equal(colored.page, undefined);
  const plain = await runCommand(["view-dumps", `${d}register-mismatch.objdump.txt`, `${d}register-mismatch.objdump.txt`]);
  assert.equal(plain.page, undefined);
  assert.equal(plain.stdout, r.stdout);
});

test("the formatter wraps like the standard text wrapper, hyphenated words included", () => {
  assert.deepEqual(wrap("Look, goof-ball -- use the -b option!", 12), ["Look, goof-", "ball -- use", "the -b", "option!"]);
  assert.deepEqual(wrap("a" .repeat(25), 10), ["aaaaaaaaaa", "aaaaaaaaaa", "aaaaa"]);
  const help = formatParserHelp({ prog: "p", actions: [], mutex: [], groups: [{ title: "options", actions: [
    { option_strings: ["-x"], dest: "x", nargs: null, choices: null, help: "default %(default)s, %% literal", default: 3, metavar: null, required: false },
    { option_strings: ["--hidden"], dest: "h", nargs: 0, help: SUPPRESS, default: false, metavar: null, required: false }] }] }, { width: 78 });
  assert.equal(help, "usage: p\n\noptions:\n  -x X  default 3, % literal\n");
});
